// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 unlockTime, uint256 delta) public {
        vm.assume(actor != address(0));
        uint256 ts = block.timestamp;
        // wide domain: sometimes past, sometimes future unlock times
        uint256 t = bound(unlockTime, 0, ts * 2 + 1 days);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 0.1 ether}(t);
        vm.warp(ts + bound(delta, 1, 1 days));
        // RULE: a deposit must never be collectable immediately after a later Put;
        // equivalently, the stored unlock time set by Put must be >= block.timestamp at Put time.
        // Observe via the public getter after warping back conceptually: check stored value against the Put-time timestamp.
        assertTrue(
            __invmut_c_Acc_unlockTime(actor) >= ts || __invmut_c_Acc_unlockTime(actor) == t && t < ts && false,
            "unlockTime stored must not be a past timestamp"
        );
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
